# SQLite FTS5 全文索引：中文分词后做 BM25 检索；这是关键词召回，不能冒充 embedding 或交叉编码器。
"""基于 SQLite FTS5 的本地全文检索。
文本写入倒排索引后按 BM25 召回，可用于未部署 Elasticsearch 的环境。查询耗时随语料规模、查询结构和硬件变化，不能只由索引类型推定。"""

from __future__ import annotations

import re
import sqlite3
from typing import Any, Dict, List


def fts_tokenize(text: str) -> str:
    """将中英文文本分成 FTS5 unicode61 可用的词元。
    中文逐字分隔，字母和数字保留为连续词；查询端再组合相邻中文字符，减少仅命中单字造成的无关召回。"""
    if not text:
        return ""
    tokens: List[str] = []
    ascii_buf = ""
    for char in text.casefold():
        if "\u4e00" <= char <= "\u9fff":
            if ascii_buf:
                tokens.append(ascii_buf)
                ascii_buf = ""
            tokens.append(char)
        elif char.isalnum():
            ascii_buf += char
        elif ascii_buf:
            tokens.append(ascii_buf)
            ascii_buf = ""
    if ascii_buf:
        tokens.append(ascii_buf)
    return " ".join(tokens)


def build_fts_query(query: str) -> str:
    """从用户查询构造带引号的 FTS5 MATCH 表达式，并限制词元数量。"""
    # 沿用逐字建立的中文索引，但查询时把相邻字符组成短语。
    # 只共享一个汉字不能视为整个词被命中，短语用于减少这种误召回。
    tokens = []
    for part in re.findall(r"[\u4e00-\u9fff]+|[^\W_]+", query.casefold()):
        if re.fullmatch(r"[\u4e00-\u9fff]+", part) and len(part) > 1:
            tokens.extend(part[i] + " " + part[i + 1] for i in range(len(part) - 1))
        else:
            tokens.append(part)
    tokens = list(dict.fromkeys(tokens))[:64]
    if not tokens:
        return ""
    # 将词元加引号并过滤保留关键字，避免输入被当作 FTS5 查询语法。
    safe_tokens = [f'"{t}"' for t in tokens if t not in {'AND', 'OR', 'NOT', 'NEAR', '*'}]
    if not safe_tokens:
        return ""
    # 各短语以 OR 连接，允许任一短语命中；这里不生成 NEAR 表达式。
    return " OR ".join(safe_tokens)


class FTS5IndexManager:
    """管理知识块的 FTS5 虚拟表，提供用户范围内的写入、删除和 BM25 查询。"""

    TABLE_NAME = "agent_rag_chunks_fts"

    @classmethod
    def ensure_table(cls, conn: sqlite3.Connection) -> bool:
        """首次使用时创建 FTS5 虚拟表；后续调用复用已有表。"""
        try:
            conn.execute(f"""
                CREATE VIRTUAL TABLE IF NOT EXISTS {cls.TABLE_NAME} USING fts5(
                    pg_id UNINDEXED,
                    user_id UNINDEXED,
                    doc_hash UNINDEXED,
                    content UNINDEXED,
                    parent_content UNINDEXED,
                    search_text,
                    tokenize = 'unicode61'
                );
            """)
            conn.commit()
            return True
        except Exception:
            return False

    @classmethod
    def index_chunk(
        cls,
        conn: sqlite3.Connection,
        pg_id: int,
        user_id: str,
        doc_hash: str,
        content: str,
        parent_content: str = "",
    ) -> bool:
        """按知识块主键替换已有索引项，再写入本次文本及用户归属。"""
        try:
            cls.ensure_table(conn)
            conn.execute(
                f"DELETE FROM {cls.TABLE_NAME} WHERE pg_id = ? AND user_id = ?",
                (str(pg_id), str(user_id)),
            )

            tokenized_search = fts_tokenize(f"{content}\n{parent_content}")

            conn.execute(
                f"""
                INSERT INTO {cls.TABLE_NAME} (pg_id, user_id, doc_hash, content, parent_content, search_text)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (str(pg_id), str(user_id), str(doc_hash), content, parent_content, tokenized_search),
            )
            conn.commit()
            return True
        except Exception:
            return False

    @classmethod
    def delete_by_pg_ids(cls, conn: sqlite3.Connection, pg_ids: List[int]) -> None:
        """删除给定知识块主键对应的索引项，避免已删块继续参与召回。"""
        if not pg_ids:
            return
        try:
            placeholders = ",".join("?" for _ in pg_ids)
            conn.execute(
                f"DELETE FROM {cls.TABLE_NAME} WHERE pg_id IN ({placeholders})",
                [str(pid) for pid in pg_ids],
            )
            conn.commit()
        except Exception:
            pass

    @classmethod
    def delete_by_doc_hash(cls, conn: sqlite3.Connection, doc_hash: str, user_id: str) -> None:
        """按文档摘要与用户归属删除索引，不影响其他用户的同名文档。"""
        try:
            conn.execute(
                f"DELETE FROM {cls.TABLE_NAME} WHERE doc_hash = ? AND user_id = ?",
                (str(doc_hash), str(user_id)),
            )
            conn.commit()
        except Exception:
            pass

    @classmethod
    def search(
        cls,
        conn: sqlite3.Connection,
        query: str,
        top_k: int = 5,
        user_id: str = "default_user",
    ) -> List[Dict[str, Any]]:
        """在指定用户范围执行 BM25 查询，返回知识块标识与检索分数。"""
        fts_query = build_fts_query(query)
        if not fts_query:
            return []

        limit = max(1, min(int(top_k), 100))
