            cursor = conn.execute(
                f"""
                SELECT pg_id, content, parent_content, bm25({cls.TABLE_NAME}) as rank
                FROM {cls.TABLE_NAME}
                WHERE {cls.TABLE_NAME} MATCH ? AND user_id = ?
                ORDER BY rank ASC

